INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 29, 'theory', 'Quiz: decorators in depth');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 29, 0, '@a over @b over def f(): in what order are the decorators applied?', '["First a, then b", "Simultaneously", "The order is random", "First b wraps f, then a wraps the result"]', 3, 'Read top to bottom, applied bottom to top: f = a(b(f)).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 29, 1, 'What does functools.wraps(func) do on a wrapper?', '["Speeds up the call", "Copies the name and docstring and sets __wrapped__, a link to the original", "Makes the function asynchronous", "Forbids decorating it again"]', 1, 'Thanks to __wrapped__, inspect.signature shows the real parameters instead of (*args, **kwargs).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 29, 2, 'Why must @classmethod be placed above your own decorator?', '["It is faster", "It is only a style convention", "Otherwise @classmethod won''t work at all", "Your wrapper must receive a function, not a classmethod descriptor"]', 3, 'classmethod, staticmethod, and property are descriptors; the lower decorator receives the function, the upper one its result.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 29, 3, 'What is wrong with an ordinary wrapper around an async def function?', '["Instead of the result it gets a coroutine and never awaits it", "Nothing", "It calls the function twice", "Async functions cannot be decorated"]', 0, 'An async wrapper with await is needed; a universal decorator chooses by inspect.iscoroutinefunction.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 29, 4, 'When does a registering decorator like @route(''/home'') run?', '["On every call of the function", "Only when the server starts", "At module import, when the function is defined", "Never by itself, you have to call it manually"]', 2, 'The decorator fires at definition time, so the module must be imported, otherwise registration doesn''t happen.');
